   "fact": "王昌龄(698—约756),唐代诗人。字少伯，盛唐著名边塞诗人，被誉为「七绝圣手」。他的边塞诗意境开阔，格调高昂，《出塞》《从军行》等作品慷慨悲壮，是唐代边塞诗的代表人物之一。代表作:《出塞》《芙蓉楼送辛渐》《从军行》。",
