   "fact": "辛弃疾(1140—1207),宋代诗人。字幼安，号稼轩，南宋豪放派词人。他文武双全，既有报国杀敌的壮志，又有深厚的文学修养。词风豪放雄健，充满爱国激情，与苏轼并称「苏辛」。代表作:《清平乐·村居》《西江月·夜行黄沙道中》《破阵子》《永遇乐》。",
