   "fact": "陶渊明(365—427),东晋代诗人。又名潜，字元亮，号五柳先生，东晋著名诗人，中国田园诗派的开创者。他不为五斗米折腰，辞官归隐，躬耕田园。其诗平淡自然，意境深远，影响深远。代表作:《饮酒》《归园田居》《桃花源记》。",
